interface MediaDragOverlayProps {
  isVisible: boolean;
  isProcessing?: boolean;
  progress?: number;
  onClick?: () => void;
  isEmptyState?: boolean;
}

export function MediaDragOverlay({
  isVisible,
  isProcessing = false,
  progress = 0,
  onClick,
  isEmptyState = false,
}: MediaDragOverlayProps) {
  if (!isVisible) return null;

  const handleClick = (e: React.MouseEvent) => {
    if (isProcessing || !onClick) return;
    e.preventDefault();
    e.stopPropagation();
    onClick();
  };

  return (
    <div
      className="flex flex-col items-center justify-center gap-4 h-full text-center bg-foreground/5 hover:bg-foreground/10 transition-all duration-200 p-8"
      onClick={handleClick}
    >
      <div className="flex items-center justify-center">
        <RiUploadLine className="h-10 w-10 text-foreground" />
      </div>

      <div className="space-y-2">
        <p className="text-xs text-muted-foreground max-w-sm">
          {isProcessing
            ? `Processing your files (${progress}%)`
            : "Drag and drop videos, photos, and audio files here"}
        </p>
      </div>

      {isProcessing && (
        <div className="w-full max-w-xs">
          <div className="w-full bg-muted/50 h-2">
            <div
              className="bg-primary h-2 transition-all duration-300"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      )}
    </div>
  );
}

